window.qaSubmits=0;document.addEventListener('submit',e=>{e.preventDefault();window.qaSubmits++;document.querySelector('#submit-count').textContent=window.qaSubmits});window.qaRead=()=>{const result={};for(const e of document.querySelectorAll('[data-qa-key]')){const k=e.dataset.qaKey;if(e.type==='radio'){if(!(k in result))result[k]='';if(e.checked)result[k]=e.value;}else if(e.type==='checkbox'&&e.name){if(!(k in result))result[k]=[];if(e.checked)result[k].push(e.value);}else if(e.type==='checkbox'){result[k]=e.checked;}else if(e.multiple){result[k]=[...e.selectedOptions].map(o=>o.value);}else result[k]=e.value;}return result;};let manualStart=null;document.querySelector('#manual-start')?.addEventListener('click',()=>{manualStart=performance.now();document.querySelector('#manual-time').textContent='计时中：按虚构原始资料手工填写并核对'});document.querySelector('#manual-stop')?.addEventListener('click',()=>{if(manualStart){const seconds=(performance.now()-manualStart)/1000;document.querySelector('#manual-time').textContent=seconds.toFixed(2)+' 秒';localStorage.setItem('qa-human-timing',JSON.stringify({seconds,at:new Date().toISOString(),values:window.qaRead()}));}});